DROP TRIGGER IF EXISTS scenarios_snapshot ON public.scenarios; DROP TRIGGER IF EXISTS scripts_snapshot ON public.scripts; DROP TABLE IF EXISTS public.scenario_versions; DROP TABLE IF EXISTS public.script_versions; CREATE TABLE public.scenario_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), scenario_id uuid NOT NULL, version int NOT NULL, title text, description text, criticality text, type text, status text, deferred boolean, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX scenario_versions_scenario_idx ON public.scenario_versions(scenario_id, version DESC); ALTER TABLE public.scenario_versions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Authenticated read scenario_versions" ON public.scenario_versions FOR SELECT TO authenticated USING (true); CREATE POLICY "Authenticated write scenario_versions" ON public.scenario_versions FOR ALL TO authenticated USING (true) WITH CHECK (true); CREATE OR REPLACE FUNCTION public.snapshot_scenario_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE next_v int; BEGIN SELECT COALESCE(MAX(version),0)+1 INTO next_v FROM public.scenario_versions WHERE scenario_id = NEW.id; INSERT INTO public.scenario_versions(scenario_id, version, title, description, criticality, type, status, deferred) VALUES (NEW.id, next_v, NEW.title, NEW.description, NEW.criticality, NEW.type, NEW.status, NEW.deferred); RETURN NEW; END; $fn$; CREATE TRIGGER scenarios_snapshot AFTER INSERT OR UPDATE ON public.scenarios FOR EACH ROW EXECUTE FUNCTION public.snapshot_scenario_version(); CREATE TABLE public.script_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), script_id uuid NOT NULL, scenario_id uuid NOT NULL, version int NOT NULL, playwright_code text, assertion_spec jsonb NOT NULL DEFAULT '{}'::jsonb, sql_template_id uuid, created_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX script_versions_script_idx ON public.script_versions(script_id, version DESC); CREATE INDEX script_versions_scenario_idx ON public.script_versions(scenario_id, version DESC); ALTER TABLE public.script_versions ENABLE ROW LEVEL SECURITY; CREATE POLICY "Authenticated read script_versions" ON public.script_versions FOR SELECT TO authenticated USING (true); CREATE POLICY "Authenticated write script_versions" ON public.script_versions FOR ALL TO authenticated USING (true) WITH CHECK (true); CREATE OR REPLACE FUNCTION public.snapshot_script_version() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $fn$ DECLARE next_v int; BEGIN SELECT COALESCE(MAX(version),0)+1 INTO next_v FROM public.script_versions WHERE script_id = NEW.id; INSERT INTO public.script_versions(script_id, scenario_id, version, playwright_code, assertion_spec, sql_template_id) VALUES (NEW.id, NEW.scenario_id, next_v, NEW.playwright_code, NEW.assertion_spec, NEW.sql_template_id); RETURN NEW; END; $fn$; CREATE TRIGGER scripts_snapshot AFTER INSERT OR UPDATE ON public.scripts FOR EACH ROW EXECUTE FUNCTION public.snapshot_script_version();